<script lang="ts">
	import { onMount } from 'svelte';
	let theme = $state<'dark' | 'light'>('dark');
	let view = $state<'overview' | 'create' | 'library'>('overview');
	let output = $state<'story' | 'character' | 'image' | 'song' | 'video'>('story');
	let prompt = $state('');
	let worldName = $state('The Saltglass Atlas');
	let genre = $state('mythic mystery');
	let rewrite = $state('');
	let status = $state('Ready for a new fragment');
	let authenticated = $state(false);
	let authOpen = $state(false);
	let authMode = $state<'signin' | 'signup'>('signin');
	let username = $state('');
	let password = $state('');
	let authError = $state('');
	onMount(async () => { const saved = localStorage.getItem('fantasy-arsenal-theme'); if (saved === 'light' || saved === 'dark') theme = saved; const session = await fetch('/api/auth/session'); if (session.ok) { authenticated = true; view = 'library'; } });
	function toggleTheme() { theme = theme === 'dark' ? 'light' : 'dark'; localStorage.setItem('fantasy-arsenal-theme', theme); }
	$effect(() => { if (typeof localStorage !== 'undefined') localStorage.setItem('fantasy-arsenal-theme', theme); });
	$effect(() => { if (authenticated && view === 'overview') view = 'library'; });
	const outputs = [{id:'story',icon:'✦',label:'Story',note:'plot, scene, arc'},{id:'character',icon:'◌',label:'Character',note:'memory, motive, voice'},{id:'image',icon:'▧',label:'Image',note:'world visual'},{id:'song',icon:'♫',label:'Song',note:'lyrics and music'},{id:'video',icon:'▹',label:'Video',note:'scene sequence'}] as const;
	function begin() { view = 'create'; status = 'Drafting a rewrite...'; rewrite = `A ${genre} tale in ${worldName}: ${prompt}`; setTimeout(() => (status = 'Rewrite ready for your approval'), 450); }
	function generate() { status = `${outputs.find((item) => item.id === output)?.label} queued after rewrite`; }
	async function submitAuth() { authError = ''; const path = authMode === 'signin' ? '/api/auth/login' : '/api/auth/signup'; const res = await fetch(path, {method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({username,password})}); const data:any = await res.json(); if (!res.ok) { authError = data.error || 'Unable to continue'; return; } authenticated = true; view = 'library'; authOpen = false; }
</script>
